s['tables']=[table('Example 7.6 solution table: age-specific fertility rates','مثال 7.6 کا حل: عمر کے لحاظ سے مخصوص شرحیں زرخیزی','د بېلګې 7.6 حل: د عمر له مخې ځانګړې د زېږون‌توان کچې',[c('Age-group','عمر کا گروہ','عمري ډله'),c('Female population in (000) (P_i)','عورتوں کی آبادی (000 میں) (P_i)','د ښځو نفوس په (000) کې (P_i)'),c('Births (B_i)','پیدائشیں (B_i)','زېږونونه (B_i)'),c('Age-specific fertility rate (B_i/P_i × 1000)','عمر کے لحاظ سے مخصوص شرحِ زرخیزی (B_i/P_i × 1000)','د عمر له مخې ځانګړې د زېږون‌توان کچه (B_i/P_i × 1000)')],[[c(r[0]),c(r[1]),c(r[2]),c(('400/16000 × 1000 = ' if r[0]=='15 – 19' else '')+r[3])] for r in fr]+[[c('Total','میزان','ټولیز'),c('92'),c('6975'),c('514')]],exampleId=E76)]
